// === Tab: mySketch ===
//music - Music by <a href="https://pixabay.com/users/rockot-1947599/?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=173062">Rockot</a> from <a href="https://pixabay.com/music//?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=173062">Pixabay</a>
let counter=0
let R=0
let G=0
let B=0
function preload() //preloads background music
{
	soundFormats('mp3', "wav");
	song = loadSound('https://openprocessing.org/sketch/2135177/files/newmusic.mp3')
}

// this class describes the properties of a single particle.
class Particle {
// setting the co-ordinates, radius and the
// speed of a particle in both the co-ordinates axes.
  constructor(){
    this.x = random(-500,width+500);
    this.y = random(-500,height+500);
    this.r = random(1);
    this.xSpeed = random(-5,5);
    this.ySpeed = random(-1,1.5);
  }

// creation of a particle.
  createParticle() {
    noStroke();
    fill(0);
    circle(this.x,this.y,this.r);
  }

// setting the particle in motion.
  moveParticle() {
    if(this.x < 100 || this.x > width+100)
      this.xSpeed*=-1;
    if(this.y < 100 || this.y > height+100)
      this.ySpeed*=-1;
    this.x+=this.xSpeed;
    this.y+=this.ySpeed;
  }

// this function creates the connections(lines)
// between particles which are less than a certain distance apart
  joinParticles(particles) {
    particles.forEach(element =>{
      let dis = dist(this.x,this.y,element.x,element.y);
      if(dis<95) {
				if(volumeLevel>=50) 
				{
					noStroke()
					this.x = random(-200,width+200);
    			this.y = random(-200,height+200);
					stroke(random(255),0,0,random(255))
					strokeWeight(.5)
				}
				else 
				{
				stroke(0)
				strokeWeight(volumeLevel/8)
				}

        line(this.x,this.y,element.x,element.y);
      }
    });
  }
}

// an array to add multiple particles
let particles = [];

function setup() {
	song.play()
	song.loop()
	amp = new p5.Amplitude();
  createCanvas(windowWidth, windowHeight);
  for(let i = 0;i<600;i++){
    particles.push(new Particle());
  }
}

function draw() {
  var vol = amp.getLevel();
  volumeLevel = round(map(vol, 0, 0.3,1, 50));
  for(let i = 0;i<particles.length;i++) {
    particles[i].createParticle();
    particles[i].moveParticle();
    particles[i].joinParticles(particles.slice(i));
  }
	let thefill=random(255)
	fill(thefill,thefill,thefill,volumeLevel/8)
	noStroke()
	rect(0,0,width,height)
	counter++
}

